package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;

final class ReportSchedulesAcceptance {
 static String path(String id){return "/api/openservice/reports/"+id+"/measurement-schedule";}
 static Map<String,Object> seed(Store store)throws Exception {String table=ReportFormsAcceptance.seed(store),report=ReportMeasurementsAcceptance.save(store,table,map("field","amount"),true);return map("table",table,"report",report);}
 static Map<String,Object> page(WorkflowSupport h,String report)throws Exception {var response=h.get(path(report),auth("admin"));assertEquals(200,response.statusCode(),html(response));return result(response);}
 static Map<String,Object> save(WorkflowSupport h,String report,int revision,boolean enabled)throws Exception {var response=h.json("POST",path(report),map("revision",revision,"interval_minutes",5,"enabled",enabled),auth("admin"));assertEquals(200,response.statusCode(),html(response));return object(result(response).get("schedule"));}
 static Map<String,Object> row(Store store,String report)throws Exception {try(var db=store.open()){PlatformFoundationTest.bind(db);return db.one("SELECT * FROM os_report_schedule WHERE report_id=? AND owner_id=?",report,db.viewerId);}}
 static void due(Store store,String report)throws Exception {try(var db=store.open()){db.update("UPDATE os_report_schedule SET next_at=? WHERE report_id=?",System.currentTimeMillis()-100000,report);db.connection.commit();}}
 static Map<String,Object> claim(Store store)throws Exception {try(var db=store.open()){var job=WorkJobs.claim(db,System.currentTimeMillis()+1000);db.connection.commit();return job;}}
 static long captures(Store store,String report)throws Exception {try(var db=store.open()){return db.count("SELECT COUNT(*) FROM os_report_measurement WHERE report_id=?",report);}}
 static void run(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();assertEquals(0,object(page(h,report).get("schedule")).get("revision"));var schedule=save(h,report,0,true);var original=row(h.store,report);ReportSchedules.dispatch(h.store);var job=claim(h.store);assertNotNull(job);var payload=Outbox.decrypt(h.store.secret,job.get("envelope").toString());assertTrue(new WorkWorker(h.store).runClaimed(job,System.currentTimeMillis()));assertEquals(1,captures(h.store,report));assertEquals("succeeded",object(page(h,report).get("schedule")).get("job_state"));var search=h.get("/api/openservice/job-search?kind=report.capture",auth("admin"));assertEquals(200,search.statusCode(),html(search));assertEquals(1,((Number)parsed(search).get("total")).intValue());assertEquals(200,h.get("/api/openservice/job-search?kind=workflow.run",auth("admin")).statusCode());assertFalse(new WorkWorker(h.store).runOne(System.currentTimeMillis()));
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(false,ReportSchedules.execute(db,job,payload).get("created"));var receipt=object(WorkJobs.detail(h.store,db,db.viewerId,job.get("job_id").toString()).get("receipt"));assertEquals(Set.of("schedule_id","measurement_id","created"),receipt.keySet());assertEquals(true,receipt.get("created"));db.connection.commit();}assertEquals(1,captures(h.store,report));try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(var record:db.all("SELECT * FROM os_record WHERE \"table\"=?",f.get("table")))Service.update(db,f.get("table").toString(),record,map("amount","10"),"admin","admin",null);db.connection.commit();}due(h.store,report);new Store(h.environment);assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(2,captures(h.store,report));var history=objects(ReportMeasurementsAcceptance.get(h,report,"").get("history"));assertEquals("50",history.getFirst().get("value"));assertEquals("10",history.getLast().get("value"));assertEquals("-40",history.getLast().get("delta"));assertTrue(((Number)row(h.store,report).get("next_at")).longValue()>System.currentTimeMillis());
  save(h,report,1,false);due(h.store,report);assertFalse(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(2,captures(h.store,report));save(h,report,2,true);assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(3,captures(h.store,report));
 }
 static void configuration(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString(),api=path(report);h.account("ScheduleAgent","agent");assertEquals(401,h.get(api,null).statusCode());assertEquals(403,h.get(api,auth("ScheduleAgent")).statusCode());assertEquals(405,h.json("DELETE",api,map(),auth("admin")).statusCode());assertEquals(400,h.get(api+"?x=1",auth("admin")).statusCode());assertEquals(400,h.get(api+"?x=1&x=2",auth("admin")).statusCode());assertEquals(404,h.get(path(id()),auth("admin")).statusCode());assertEquals(403,h.form("/reports/"+report+"/measurement-schedule",map("revision","0","interval_minutes","5","enabled","true"),auth("admin")).statusCode());
  for(var body:List.of(map(),map("revision","0","interval_minutes",5,"enabled",true),map("revision",-1,"interval_minutes",5,"enabled",true),map("revision",0,"interval_minutes","5","enabled",true),map("revision",0,"interval_minutes",4,"enabled",true),map("revision",0,"interval_minutes",10081,"enabled",true),map("revision",0,"interval_minutes",5,"enabled","true")))assertEquals(400,h.json("POST",api,body,auth("admin")).statusCode());assertEquals(409,h.json("POST",api,map("revision",1,"interval_minutes",5,"enabled",true),auth("admin")).statusCode());save(h,report,0,false);assertEquals(409,h.json("POST",api,map("revision",0,"interval_minutes",5,"enabled",true),auth("admin")).statusCode());assertEquals(200,h.json("POST",api,map("revision",1,"interval_minutes",10080,"enabled",true),auth("admin")).statusCode());String grouped=ReportMeasurementsAcceptance.save(h.store,f.get("table").toString(),map("field","amount","group_by","short_description"),false);assertEquals(400,h.get(path(grouped),auth("admin")).statusCode());assertEquals(400,h.json("POST",path(grouped),map("revision",0,"interval_minutes",5,"enabled",true),auth("admin")).statusCode());
 }
 static void isolation(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();h.account("ScheduleOther","admin");save(h,report,0,true);assertEquals(0,object(result(h.get(path(report),auth("ScheduleOther"))).get("schedule")).get("revision"));assertEquals(200,h.json("POST",path(report),map("revision",0,"interval_minutes",10,"enabled",true),auth("ScheduleOther")).statusCode());ReportSchedules.dispatch(h.store);new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000);new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000);assertEquals(2,captures(h.store,report));assertEquals(1,objects(ReportMeasurementsAcceptance.get(h,report,"").get("history")).size());assertEquals(1,objects(result(h.get(ReportMeasurementsAcceptance.path(report),auth("ScheduleOther"))).get("history")).size());try(var db=h.store.open()){PlatformFoundationTest.bind(db);var row=db.one("SELECT * FROM os_report_schedule WHERE report_id=? AND owner_id<>?",report,db.viewerId);assertEquals(404,assertThrows(Failure.class,()->ReportSchedules.authority(db,row.get("schedule_id").toString(),db.viewerId)).status);db.update("UPDATE os_saved_report SET shared=0 WHERE report_id=?",report);db.connection.commit();}assertEquals(404,h.get(path(report),auth("ScheduleOther")).statusCode());due(h.store,report);ReportSchedules.dispatch(h.store);try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(0,db.count("SELECT enabled FROM os_report_schedule WHERE report_id=? AND owner_id<>?",report,db.viewerId));assertEquals(1,db.count("SELECT enabled FROM os_report_schedule WHERE report_id=? AND owner_id=?",report,db.viewerId));}
 }
 static void invalidation(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();save(h,report,0,true);ReportSchedules.dispatch(h.store);var old=claim(h.store);save(h,report,1,false);new WorkWorker(h.store).runClaimed(old,System.currentTimeMillis());assertEquals(0,captures(h.store,report));assertEquals("cancelled",object(page(h,report).get("schedule")).get("job_state"));save(h,report,2,true);ReportSchedules.dispatch(h.store);old=claim(h.store);save(h,report,3,true);new WorkWorker(h.store).runClaimed(old,System.currentTimeMillis());assertEquals(0,captures(h.store,report));assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(1,captures(h.store,report));
  due(h.store,report);ReportSchedules.dispatch(h.store);old=claim(h.store);try(var db=h.store.open()){PlatformFoundationTest.bind(db);db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",db.viewerId);db.connection.commit();}new WorkWorker(h.store).runClaimed(old,System.currentTimeMillis());assertEquals(1,captures(h.store,report));due(h.store,report);ReportSchedules.dispatch(h.store);assertEquals(0,((Number)row(h.store,report).get("enabled")).intValue());assertEquals("REPORT_OR_AUTHORITY_UNAVAILABLE",row(h.store,report).get("status"));save(h,report,4,true);assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(2,captures(h.store,report));
 }
 static void definition(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();save(h,report,0,true);ReportSchedules.dispatch(h.store);var job=claim(h.store);try(var db=h.store.open()){PlatformFoundationTest.bind(db);SavedReports.save(db,db.viewerId,report,map("name","Changed sampling","table",f.get("table"),"query",map("field","amount","q","short_description=Visible"),"shared",true));db.connection.commit();}new WorkWorker(h.store).runClaimed(job,System.currentTimeMillis());assertEquals(0,captures(h.store,report));due(h.store,report);ReportSchedules.dispatch(h.store);assertEquals(0,((Number)row(h.store,report).get("enabled")).intValue());save(h,report,1,true);assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(1,captures(h.store,report));try(var db=h.store.open()){PlatformFoundationTest.bind(db);SavedReports.remove(db,db.viewerId,report);assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_schedule WHERE report_id=?",report));db.connection.commit();}assertEquals(404,h.get(path(report),auth("admin")).statusCode());
 }
 static void jobs(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();save(h,report,0,true);var row=row(h.store,report);var body=ReportSchedules.payload(row);try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(var bad:List.of(map(),map("schedule_id","bad","revision",1,"scheduled_at",0),map("schedule_id",row.get("schedule_id"),"revision","1","scheduled_at",0),map("schedule_id",row.get("schedule_id"),"revision",1,"scheduled_at","0")))assertEquals(400,assertThrows(Failure.class,()->ReportSchedules.validate(db,db.viewerId,"bad",bad)).status);assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.validate(db,db.viewerId,"bad",body)).status);var stale=new LinkedHashMap<>(body);stale.put("revision",0);assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.validate(db,db.viewerId,ReportSchedules.key(stale),stale)).status);stale.put("revision",1);stale.put("scheduled_at",0);assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.validate(db,db.viewerId,ReportSchedules.key(stale),stale)).status);db.update("UPDATE os_report_schedule SET next_at=? WHERE report_id=?",System.currentTimeMillis()+600000,report);db.connection.commit();}row=row(h.store,report);var future=ReportSchedules.payload(row);try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.validate(db,db.viewerId,ReportSchedules.key(future),future)).status);}due(h.store,report);ReportSchedules.dispatch(h.store);var queued=row(h.store,report);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var again=ReportSchedules.payload(queued);db.update("UPDATE os_report_schedule SET next_at=? WHERE report_id=?",System.currentTimeMillis()-10000,report);again.put("scheduled_at",db.count("SELECT next_at FROM os_report_schedule WHERE report_id=?",report));assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.validate(db,db.viewerId,ReportSchedules.key(again),again)).status);WorkJobs.control(db,db.viewerId,queued.get("last_job").toString(),"cancel");db.connection.commit();}assertEquals(0,captures(h.store,report));assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals(1,captures(h.store,report));
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();save(h,report,0,true);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{ReportSchedules.dispatch(h.store);return true;});var b=pool.submit(()->{ReportSchedules.dispatch(h.store);return true;});assertTrue(a.get());assertTrue(b.get());}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_work WHERE kind='report.capture'"));}try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));var b=pool.submit(()->new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertNotEquals(a.get(),b.get());}assertEquals(1,captures(h.store,report));var body=map("revision",1,"interval_minutes",5,"enabled",true);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->h.json("POST",path(report),body,auth("admin")).statusCode());var b=pool.submit(()->h.json("POST",path(report),body,auth("admin")).statusCode());assertEquals(Set.of(200,409),Set.of(a.get(),b.get()));}
 } static void authority(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();h.account("ScheduleOwner","admin");String schedule,owner;try(var db=h.store.open()){var actor=ApprovalTest.as(db,"ScheduleOwner");owner=db.viewerId;schedule=object(ReportSchedules.save(db,report,map("revision",0,"interval_minutes",5,"enabled",true)).get("schedule")).get("schedule_id").toString();db.connection.commit();}
  for(String mutation:List.of("active=0","role='agent'","password_reset_required=1"))try(var db=h.store.open()){db.update("UPDATE os_user SET "+mutation+" WHERE user_id=?",owner);assertEquals(403,assertThrows(Failure.class,()->ReportSchedules.authority(db,schedule,owner)).status);db.connection.rollback();}
  try(var db=h.store.open()){db.update("DELETE FROM os_user WHERE user_id=?",owner);assertEquals(403,assertThrows(Failure.class,()->ReportSchedules.authority(db,schedule,owner)).status);ReportSchedules.cleanup(db);assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_schedule"));db.connection.rollback();}
  Map<String,Object> definition;try(var db=h.store.open()){PlatformFoundationTest.bind(db);definition=Service.schema(db,f.get("table").toString());var denied=new LinkedHashMap<>(definition);denied.put("record_roles",map("read",List.of("agent")));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(denied),f.get("table"));db.connection.commit();}ReportSchedules.dispatch(h.store);try(var db=h.store.open()){assertEquals(0,db.count("SELECT enabled FROM os_report_schedule WHERE schedule_id=?",schedule));assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_measurement"));db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(definition),f.get("table"));db.connection.commit();}
  try(var db=h.store.open()){ApprovalTest.as(db,"ScheduleOwner");ReportSchedules.save(db,report,map("revision",1,"interval_minutes",5,"enabled",true));db.connection.commit();}ReportSchedules.dispatch(h.store);var job=claim(h.store);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var denied=Service.schema(db,f.get("table").toString());object(denied.get("fields")).remove("amount");object(denied.get("field_rules")).remove("amount");db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(denied),f.get("table"));db.connection.commit();}try{new WorkWorker(h.store).runClaimed(job,System.currentTimeMillis());assertEquals(0,captures(h.store,report));}finally{try(var db=h.store.open()){db.update("UPDATE os_schema SET definition="+db.jsonParameter()+" WHERE name=?",JSON.writeValueAsString(definition),f.get("table"));db.connection.commit();}}
 }
 static void limits(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();try(var db=h.store.open()){for(int n=0;n<200;n++)db.update("INSERT INTO os_report_schedule(schedule_id,report_id,owner_id,revision,auth_revision,definition_hash,interval_minutes,enabled,next_at,last_job,status) VALUES(?,?,?,1,0,'',5,1,0,'','enabled')",id(),id(),id());db.connection.commit();}assertEquals(400,h.json("POST",path(report),map("revision",0,"interval_minutes",5,"enabled",true),auth("admin")).statusCode());try(var db=h.store.open()){ReportSchedules.cleanup(db);assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_schedule"));PlatformFoundationTest.bind(db);for(int n=0;n<12;n++){String next=SavedReports.save(db,db.viewerId,map("name","Schedule limit "+n,"table",f.get("table"),"query",map("field","amount"),"shared",false)).get("report_id").toString();ReportSchedules.save(db,next,map("revision",0,"interval_minutes",5,"enabled",true));}db.connection.commit();}ReportSchedules.dispatch(h.store);try(var db=h.store.open()){assertEquals(10,db.count("SELECT COUNT(*) FROM os_work WHERE kind='report.capture'"));}ReportSchedules.dispatch(h.store);try(var db=h.store.open()){assertEquals(12,db.count("SELECT COUNT(*) FROM os_work WHERE kind='report.capture'"));}ReportSchedules.dispatch(h.store);try(var db=h.store.open()){assertEquals(12,db.count("SELECT COUNT(*) FROM os_work WHERE kind='report.capture'"));}
 }
 static void proofs(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();save(h,report,0,true);ReportSchedules.dispatch(h.store);var job=claim(h.store);var body=Outbox.decrypt(h.store.secret,job.get("envelope").toString());try(var db=h.store.open()){PlatformFoundationTest.bind(db);var forged=new LinkedHashMap<>(job);forged.put("job_id",id());assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.execute(db,forged,body)).status);forged.put("job_id",job.get("job_id"));forged.put("dedupe","wrong");assertEquals(409,assertThrows(Failure.class,()->ReportSchedules.execute(db,forged,body)).status);assertEquals(0,db.count("SELECT COUNT(*) FROM os_report_measurement"));db.update("DELETE FROM os_saved_report WHERE report_id=?",report);db.connection.commit();}new WorkWorker(h.store).runClaimed(job,System.currentTimeMillis());assertEquals(0,captures(h.store,report));ReportSchedules.dispatch(h.store);assertNull(row(h.store,report));
 }
 static void retries(WorkflowSupport h)throws Exception {
  var f=seed(h.store);String report=f.get("report").toString();save(h,report,0,true);ReportSchedules.dispatch(h.store);var job=claim(h.store);
  try(var db=h.store.open()){if(db.postgres){db.update("CREATE FUNCTION test_measurement_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'temporary capture storage failure'; END $$");db.update("CREATE TRIGGER test_measurement_failure BEFORE INSERT ON os_report_measurement FOR EACH ROW EXECUTE FUNCTION test_measurement_failure()");}else db.update("CREATE TRIGGER test_measurement_failure BEFORE INSERT ON os_report_measurement BEGIN SELECT RAISE(ABORT,'temporary capture storage failure'); END");db.connection.commit();}
  try{new WorkWorker(h.store).runClaimed(job,System.currentTimeMillis());assertEquals(0,captures(h.store,report));try(var db=h.store.open()){assertEquals("queued",db.one("SELECT state FROM os_work WHERE job_id=?",job.get("job_id")).get("state"));assertEquals("EXECUTION_FAILED",db.one("SELECT error FROM os_work WHERE job_id=?",job.get("job_id")).get("error"));}}finally{try(var db=h.store.open()){db.update("DROP TRIGGER test_measurement_failure"+(db.postgres?" ON os_report_measurement":""));if(db.postgres)db.update("DROP FUNCTION test_measurement_failure()");db.connection.commit();}}
  assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+6000));assertEquals(1,captures(h.store,report));try(var db=h.store.open()){assertEquals(2,db.count("SELECT attempts FROM os_work WHERE job_id=?",job.get("job_id")));assertEquals(2,db.count("SELECT COUNT(*) FROM os_work_attempt WHERE job_id=?",job.get("job_id")));}
  due(h.store,report);ReportSchedules.dispatch(h.store);var leased=claim(h.store);Map<String,Object> replacement;try(var db=h.store.open()){replacement=WorkJobs.claim(db,System.currentTimeMillis()+125000);db.connection.commit();}assertNotNull(replacement);new WorkWorker(h.store).runClaimed(leased,System.currentTimeMillis());assertEquals(1,captures(h.store,report));new WorkWorker(h.store).runClaimed(replacement,System.currentTimeMillis());assertEquals(2,captures(h.store,report));
 }

}
